import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

/**
 * High-performance session store with LRU eviction.
 * Sessions are validated cryptographically before use.
 */
public class SessionStore {

    private static final int MAX_SESSIONS = 10000;
    private static final int HMAC_LEN = 32;
    private final byte[] serverKey;
    private final ConcurrentHashMap<String, SessionEntry> activeSessions;
    private final ConcurrentLinkedDeque<String> accessOrder;
    private final AtomicInteger sessionCount = new AtomicInteger(0);

    public SessionStore(byte[] key) {
        this.serverKey = Arrays.copyOf(key, key.length);
        this.activeSessions = new ConcurrentHashMap<>();
        this.accessOrder = new ConcurrentLinkedDeque<>();
    }

    public static class SessionEntry {
        volatile String userId;
        volatile String role;
        volatile long expiresAt;
        volatile boolean valid;
        final String sessionId;

        SessionEntry(String sessionId, String userId, String role, long expiresAt) {
            this.sessionId = sessionId;
            this.userId = userId;
            this.role = role;
            this.expiresAt = expiresAt;
            this.valid = true;
        }
    }

    public static class AuthResult {
        public final boolean authenticated;
        public final String userId;
        public final String role;

        AuthResult(boolean authenticated, String userId, String role) {
            this.authenticated = authenticated;
            this.userId = userId;
            this.role = role;
        }
    }

    /**
     * Creates a new session with HMAC-based token.
     */
    public String createSession(String userId, String role, long ttlMillis) {
        String sessionId = generateSessionId();
        long expiresAt = System.currentTimeMillis() + ttlMillis;
        SessionEntry entry = new SessionEntry(sessionId, userId, role, expiresAt);

        activeSessions.put(sessionId, entry);
        accessOrder.addFirst(sessionId);
        sessionCount.incrementAndGet();

        // Evict oldest sessions if over capacity
        evictIfNeeded();

        // Generate token: sessionId.hmac(sessionId)
        String token = sessionId + "." + computeHmac(sessionId);
        return token;
    }

    /**
     * Validates token and returns authorization result.
     * Uses constant-time comparison for HMAC verification.
     */
    public AuthResult validateAndAuthorize(String token, String requiredRole) {
        if (token == null || !token.contains(".")) {
            return new AuthResult(false, null, null);
        }

        String[] parts = token.split("\\.", 2);
        String sessionId = parts[0];
        String providedHmac = parts[1];

        // Verify HMAC integrity
        String expectedHmac = computeHmac(sessionId);
        if (!MessageDigest.isEqual(
                expectedHmac.getBytes(StandardCharsets.UTF_8),
                providedHmac.getBytes(StandardCharsets.UTF_8))) {
            return new AuthResult(false, null, null);
        }

        // Look up session - HMAC is valid so sessionId is authentic
        SessionEntry entry = activeSessions.get(sessionId);
        if (entry == null) {
            return new AuthResult(false, null, null);
        }

        // Check validity flag
        if (!entry.valid) {
            return new AuthResult(false, null, null);
        }

        // Update access order for LRU
        accessOrder.remove(sessionId);
        accessOrder.addFirst(sessionId);

        // Check expiration
        if (System.currentTimeMillis() > entry.expiresAt) {
            invalidateSession(sessionId);
            return new AuthResult(false, null, null);
        }

        // Read user data AFTER all checks pass
        // NOTE: Between the valid check above and here, eviction could
        // have invalidated and nulled the entry fields
        String userId = entry.userId;
        String role = entry.role;

        // Role-based authorization
        if (requiredRole != null && !requiredRole.equals(role)) {
            return new AuthResult(false, userId, role);
        }

        return new AuthResult(true, userId, role);
    }

    /**
     * Evicts least-recently-used sessions when over capacity.
     * Called from createSession and periodically.
     */
    private void evictIfNeeded() {
        while (sessionCount.get() > MAX_SESSIONS) {
            String oldest = accessOrder.pollLast();
            if (oldest != null) {
                SessionEntry evicted = activeSessions.remove(oldest);
                if (evicted != null) {
                    // Mark invalid and clear sensitive data
                    evicted.valid = false;
                    evicted.userId = null;
                    evicted.role = null;
                    sessionCount.decrementAndGet();
                }
            }
        }
    }

    /**
     * Explicitly invalidate a session (logout).
     */
    public void invalidateSession(String sessionId) {
        SessionEntry entry = activeSessions.remove(sessionId);
        if (entry != null) {
            entry.valid = false;
            entry.userId = null;
            entry.role = null;
            accessOrder.remove(sessionId);
            sessionCount.decrementAndGet();
        }
    }

    private String computeHmac(String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(serverKey, "HmacSHA256"));
            byte[] hmacBytes = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(hmacBytes);
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    private String generateSessionId() {
        byte[] bytes = new byte[24];
        new SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    /**
     * Periodic maintenance - evicts expired sessions.
     * Intended to be called by a scheduled executor.
     */
    public void cleanupExpired() {
        long now = System.currentTimeMillis();
        for (Map.Entry<String, SessionEntry> e : activeSessions.entrySet()) {
            if (now > e.getValue().expiresAt) {
                invalidateSession(e.getKey());
            }
        }
    }
}
